import{_ as i,o as s,c as t,a3 as a}from"./chunks/framework.DAK02U1-.js";const k=JSON.parse('{"title":"Indexing","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Indexing | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/guide/indexing"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/guide/indexing"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/guide/indexing"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/guide/indexing"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/guide/indexing"}]]},"headers":[],"relativePath":"clice/guide/indexing.md","filePath":"en/clice/guide/indexing.md","lastUpdated":1794682313000}'),n={name:"clice/guide/indexing.md"};function r(o,e,h,l,d,p){return s(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="indexing" tabindex="-1">Indexing <a class="header-anchor" href="#indexing" aria-label="Permalink to &quot;Indexing&quot;">​</a></h1><p>The answers that reach beyond the files you have open — references, call and type hierarchies, workspace symbols, rename, and hover or navigation on a file not compiled yet — come from clice&#39;s index of the project. This page says what goes into it and how to make the first index of a big project take less time.</p><h2 id="what-gets-indexed" tabindex="-1">What Gets Indexed <a class="header-anchor" href="#what-gets-indexed" aria-label="Permalink to &quot;What Gets Indexed&quot;">​</a></h2><p>When the server starts, the background index compiles every translation unit of the project: each file of its compilation databases, the sources a rule&#39;s <code>default_command</code> covers, and the files opened earlier that no database lists. It waits until you have been idle for <code>background_delay_ms</code>, runs on the background workers, and gives way to the requests of the files you work on. A header is indexed through the units that include it, once for each way they include it, so a header compiled differently by different sources answers for each of those contexts.</p><p>For each file the index records its declarations, definitions and references, what calls what, what derives from what, and the template instantiations the units make. Inside a function body it records the names the body uses, unless <code>index_function_body</code> leaves the file&#39;s bodies out: by default the bodies of system headers (the standard library, an <code>-isystem</code> directory) are left out, and so are the instantiations of templates written there. The rest of a system header — its declarations, its types, its templates — is indexed.</p><p>The index is saved in the cache directory. The next server, or <code>clice index</code> run, loads it and compiles again only the units whose files changed since. <code>clice index</code> builds or updates the index from the command line; while a server serves the project, it asks that server to do it.</p><h2 id="a-faster-first-index" tabindex="-1">A Faster First Index <a class="header-anchor" href="#a-faster-first-index" aria-label="Permalink to &quot;A Faster First Index&quot;">​</a></h2><p>The first index of a big project compiles every unit once. Three things shorten it:</p><ul><li><strong>More workers.</strong> <code>[workers] background</code> is how many units compile at once: by default half the machine&#39;s physical cores. On a machine with many cores and memory to spare, raise it.</li><li><strong>Fewer units.</strong> A rule with <code>background_index = false</code> keeps the files it matches from being compiled as units of their own: tests, examples, benchmarks or generated sources you do not navigate in. A header they include is still indexed through the other units including it.</li><li><strong>Skipped bodies.</strong> A rule with <code>skip_function_body = true</code> makes every compile but the file&#39;s own skip the function bodies of the files it matches, templates included, in the editor and in the background index alike. Put it on third-party code: the units of your project then parse only the declarations of the libraries they include, and a module of the library they import is built with its bodies skipped too. Function templates that forward their arguments, such as <code>std::make_unique</code>, are still parsed, and so are <code>constexpr</code> functions and those returning <code>auto</code>, which the compiler needs.</li></ul><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;third_party/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;external/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">skip_function_body = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">background_index = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lint = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">format = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;benchmarks/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">background_index = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">workers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">background = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span></span></code></pre></div><p>What skipping costs: the errors inside those bodies are not reported, nor the errors your code causes when it instantiates their templates, and the names their bodies use are not indexed — references and call hierarchies stop at their declarations. <code>skip_function_body = false</code> turns skipping off everywhere, the editor&#39;s own included: by default the editor skips the bodies of the headers at the top of an open file and the background index parses them, reporting what it finds there on the file.</p><h2 id="library-internals" tabindex="-1">Library Internals <a class="header-anchor" href="#library-internals" aria-label="Permalink to &quot;Library Internals&quot;">​</a></h2><p>To navigate inside the standard library or another system library — find the callers of a function within it, or the instantiations of its templates — let a rule index its bodies:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/usr/include/c++/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">index_function_body = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>The index grows with every body it records, so this is best kept to the libraries you read.</p>`,15)])])}const u=i(n,[["render",r]]);export{k as __pageData,u as default};
